g/products/115-175-207", "aliases": [], "codes": []}, {"name": "Cy2 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-225-207", "size": "0.5", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-225-207", "aliases": [], "codes": []}, {"name": "Rhodamine Red-X (RRX) AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-295-207", "size": "0.5", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-295-207", "aliases": [], "codes": []}, {"name": "DyLight 405 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-475-207", "size": "0.5", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-475-207", "aliases": [], "codes": []}, {"name": "Alexa Fluor 488 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-545-207", "size": "0.5", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-545-207", "aliases": [], "codes": []}, {"name": "Alexa Fluor 555 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-565-207", "size": "0.5", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-565-207", "aliases": [], "codes": []}, {"name": "Alexa Fluor 568 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-575-207", "size": "0.5", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-575-207", "aliases": [], "codes": []}, {"name": "Alexa Fluor 594 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-585-207", "size": "0.5", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-585-207", "aliases": [], "codes": []}, {"name": "Alexa Fluor 647 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-605-207", "size": "0.5", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-605-207", "aliases": [], "codes": []}, {"name": "Alexa Fluor 680 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-625-207", "size": "0.3", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-625-207", "aliases": [], "codes": []}, {"name": "Alexa Fluor 790 AffiniPure Goat Anti-Mouse IgG, Fcγ subclass 2b specific, Whole IgG (min X Hu, Bov, Rb Sr Prot)", "supplier": "Jackson ImmunoResearch", "catalogue": "115-655-207", "size": "0.3", "unit": "mg", "url": "https://www.jacksonimmuno.com/catalog/products/115-655-207", "aliases": [], "codes": []}]$batch_a76d161cffadf9ccdc1900b7f56690a6b6a1182cad8a02dd48fe0d28a6be3a80$::jsonb) as products(name text, supplier text, catalogue text, size numeric, unit text, url text, aliases text[], codes text[])
  loop
    insert into public.product_catalogue(name, manufacturer_supplier, catalogue_number, container_size, unit, product_url)
      values(reference.name, reference.supplier, reference.catalogue, reference.size, reference.unit, reference.url)
      on conflict do nothing;
    get diagnostics inserted_count = row_count;
    added := added + inserted_count;
    select * into saved_product from public.product_catalogue
      where lower(manufacturer_supplier) = lower(reference.supplier) and lower(catalogue_number) = lower(reference.catalogue)
        and (case when unit in ('L', 'mL', 'µL') then 'volume' when unit in ('kg', 'g', 'mg') then 'mass' else 'count' end)
          = (case when reference.unit in ('L', 'mL', 'µL') then 'volume' when reference.unit in ('kg', 'g', 'mg') then 'mass' else 'count' end)
        and container_size * case when unit in ('L', 'kg') then 1000000 when unit in ('mL', 'g') then 1000 else 1 end
          = reference.size * case when reference.unit in ('L', 'kg') then 1000000 when reference.unit in ('mL', 'g') then 1000 else 1 end
      for update;
    if lower(saved_product.name) <> lower(reference.name) or saved_product.product_url is distinct from reference.url then
      skipped := skipped + 1;
      raise notice 'Existing reference differs for % / %. Details and mappings left untouched.', reference.supplier, reference.catalogue;
      continue;
    end if;
    foreach alias_value in array coalesce(reference.aliases, array[]::text[]) loop
      insert into public.product_catalogue_aliases(catalogue_number, product_id) values(alias_value, saved_product.id) on conflict do nothing;
    end loop;
    foreach code_value in array coalesce(reference.codes, array[]::text[]) loop
      insert into public.product_catalogue_codes(code, product_id) values(code_value, saved_product.id) on conflict do nothing;
      select product_id into mapped_product from public.product_catalogue_codes where code = code_value;
      if mapped_product <> saved_product.id then
        raise notice 'Code % already belongs to another product; mapping left untouched.', code_value;
      end if;
    end loop;
  end loop;
  raise notice 'Catalogue expansion: % new products, % conflicting existing references skipped. No lab inventory changed.', added, skipped;
end;
